package com.mahesh.empleave.holiday;import jakarta.persistence.*;import lombok.*;import java.time.*;@Entity @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class Holiday{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,unique=true) private LocalDate holidayDate;@Column(nullable=false) private String name;public Holiday(LocalDate d,String n){holidayDate=d;name=n;}public void update(LocalDate d,String n){holidayDate=d;name=n;}}
